// ---- the 2sl kit's transport clock (src/2sl-kit-clock.template.js, from 2sl stab) ----------------
// The patch sends `tick <ticks>` on every 16th while Live plays: a [metro 16n @quantize 16n] bang asks
// [transport] for Live's song position in ticks (480 per quarter note, whatever the time signature). Every 16th
// of the song is played exactly once: a second bang on the same 16th is ignored, and a bang between 16ths (the
// metro's immediate bang when Live starts mid-16th) plays nothing, since that 16th began before we heard it.
// The script that includes this defines `playing` (Live's transport, 0/1) and playSixteenth(songSixteenth).
var TICKS_PER_SIXTEENTH = 120;        // Max: 480 ticks per quarter note
var ON_SIXTEENTH_TOLERANCE = 0.25;    // a bang within a quarter of a 16th of one is on it (clock jitter)
var lastPlayedSixteenth = null;       // song position (in 16ths) of the last 16th played while Live plays

function tick(ticks) {
  if (!playing) return;
  if (!isFinite(ticks)) {
    error(DEVICE_NAME + ": the clock got a song position of " + ticks + " ticks: 16th skipped\n");
    return;
  }
  var position = ticks / TICKS_PER_SIXTEENTH;
  var nearest = Math.round(position);
  if (Math.abs(position - nearest) > ON_SIXTEENTH_TOLERANCE) {
    lastPlayedSixteenth = Math.floor(position);
    return;
  }
  if (nearest === lastPlayedSixteenth) return;
  if (lastPlayedSixteenth !== null && nearest > lastPlayedSixteenth + 1) {
    post(DEVICE_NAME + ": the song position jumped from 16th " + lastPlayedSixteenth + " to " + nearest +
         " (a locate, or a late clock): the 16ths between were not played\n");
  }
  lastPlayedSixteenth = nearest;
  playSixteenth(nearest);
}

/** Live started or stopped: the next tick starts afresh. */
function resetClock() { lastPlayedSixteenth = null; }
// ---- end of the kit's transport clock ------------------------------------------------------------

// ---- helpers ----------------------------------------------------------------------------------------

function emptyRow() { var row = []; for (var s = 0; s < STEPS; s++) row.push(0); return row; }

/** A row from its text (16 of . o x X). Bad text is a broken build or message: it throws, with the text. */
function parseRow(rowText, where) {
  if (typeof rowText !== "string" || rowText.length !== STEPS) {
    throw new Error(DEVICE_NAME + ": " + where + ": row '" + rowText + "' is not " + STEPS + " steps");
  }
  var row = [];
  for (var s = 0; s < STEPS; s++) {
    var grade = GRADE_CHARACTERS.indexOf(rowText.charAt(s));
    if (grade < 0) throw new Error(DEVICE_NAME + ": " + where + ": row '" + rowText + "' has '" + rowText.charAt(s) + "' (use . o x X)");
    row.push(grade);
  }
  return row;
}
function rowText(row) { var t = ""; for (var s = 0; s < STEPS; s++) t += GRADE_CHARACTERS.charAt(row[s]); return t; }
function rowHasHits(row) { for (var s = 0; s < STEPS; s++) if (row[s] > 0) return true; return false; }
function randomInt(count) { return Math.floor(Math.random() * count) % count; }
function randomByte() { return randomInt(256); }

/** A control value outside its range can only come from a wiring or message error: logged, then clamped. */
function controlInt(control, value, low, high) {
  var rounded = Math.round(value);
  if (!(rounded >= low && rounded <= high)) {
    var used = Math.max(low, Math.min(high, isFinite(rounded) ? rounded : low));
    error(DEVICE_NAME + ": " + control + " got " + value + ", outside " + low + ".." + high +
          " (a wiring or message error): using " + used + "\n");
    return used;
  }
  return rounded;
}
function controlUnit(control, value) {
  if (!(value >= 0 && value <= 1)) {
    var used = Math.max(0, Math.min(1, isFinite(value) ? value : 0));
    error(DEVICE_NAME + ": " + control + " got " + value + ", outside 0..1 (a wiring or message error): using " + used + "\n");
    return used;
  }
  return value;
}
function voiceArgument(control, value) { return controlInt(control + "'s voice", value, 0, VOICES.length - 1); }

// ---- Grids (patterns.md P12, B1) ----------------------------------------------------------------------

/** avrlib U8Mix: a crossfade of two bytes by `balance` 0-255. */
function u8Mix(a, b, balance) { return (a * (255 - balance) + b * balance) >> 8; }

/** Grids' ReadDrumMap: the level of `step` (0-31, 32nds) for `instrument` (0 BD, 1 SD, 2 HH) at map point
 *  x, y (0-255), bilinear between the four nearest nodes. */
function gridsLevel(step, instrument, x, y) {
  var i = x >> 6, j = y >> 6;
  var offset = instrument * 32 + step;
  var a = GRIDS_NODES[GRIDS_DRUM_MAP[i][j]][offset];
  var b = GRIDS_NODES[GRIDS_DRUM_MAP[i + 1][j]][offset];
  var c = GRIDS_NODES[GRIDS_DRUM_MAP[i][j + 1]][offset];
  var d = GRIDS_NODES[GRIDS_DRUM_MAP[i + 1][j + 1]][offset];
  var xBalance = (x << 2) & 255, yBalance = (y << 2) & 255;
  return u8Mix(u8Mix(a, b, xBalance), u8Mix(c, d, xBalance), yBalance);
}

/** A level 0-255 as a grade, by patterns.md F's legend: X > 192, x 100-192, o 40-99, . < 40. */
function gradeForLevel(level) { return level > 192 ? 3 : level >= 100 ? 2 : level >= 40 ? 1 : 0; }

/** Voice v's row at a Grids map point: its channel's 16ths (the even 32nd steps), shaped as VOICES says. */
function gridsRow(v, x, y) {
  var channel = VOICES[v].grids;
  if (!channel) return null;
  var row = [];
  for (var s = 0; s < STEPS; s++) {
    var grade = gradeForLevel(gridsLevel(2 * s, channel.instrument, x, y));
    if (channel.keep === "accents" && grade < 3) grade = 0;
    if (channel.keep === "offbeat eighths" && s % 4 !== 2) grade = 0;
    row.push(grade);
  }
  return row;
}

// ---- Euclidean rhythms (patterns.md P11, Toussaint) ---------------------------------------------------

/** Bjorklund's algorithm as Toussaint gives it: k onsets spread as evenly as possible over n steps. */
function euclidean(k, n) {
  if (!(k >= 0 && k <= n && n >= 1)) throw new Error(DEVICE_NAME + ": E(" + k + "," + n + ") doesn't exist");
  var groups = [], remainders = [], i;
  if (k === 0 || k === n) { for (i = 0; i < n; i++) groups.push(k ? 1 : 0); return groups; }
  for (i = 0; i < k; i++) groups.push([1]);
  for (i = 0; i < n - k; i++) remainders.push([0]);
  // pair a remainder onto each group, then the leftovers become the remainders; at least once, until one is left
  do {
    var pairs = Math.min(groups.length, remainders.length), merged = [];
    for (i = 0; i < pairs; i++) merged.push(groups[i].concat(remainders[i]));
    var leftover = groups.length > pairs ? groups.slice(pairs) : remainders.slice(pairs);
    groups = merged;
    remainders = leftover;
  } while (remainders.length > 1);
  var out = [];
  for (i = 0; i < groups.length; i++) out = out.concat(groups[i]);
  for (i = 0; i < remainders.length; i++) out = out.concat(remainders[i]);
  return out;
}
/** E(k, 16) rotated `rotation` steps later, as a row of hits. */
function euclideanRow(k, rotation) {
  var onsets = euclidean(k, STEPS), row = [];
  for (var s = 0; s < STEPS; s++) row.push(onsets[(s - rotation + STEPS) % STEPS] ? 2 : 0);
  return row;
}

// ---- loading, generating, rerolling --------------------------------------------------------------------

function currentStyle() { return STYLES[styleIndex]; }

/** Every voice that isn't locked gets `rowFor(v)` -> {row, source} (or null: keeps its row, and says so). */
function setUnlockedRows(rowFor, what) {
  var kept = [];
  for (var v = 0; v < VOICES.length; v++) {
    if (locks[v]) continue;
    var made = rowFor(v);
    if (!made) { kept.push(VOICES[v].name); continue; }
    pattern[v] = made.row;
    rowSources[v] = made.source;
  }
  if (kept.length) post(DEVICE_NAME + ": " + what + ": " + currentStyle().name + " has nothing for " + kept.join(", ") +
                        ": kept as they were\n");
}

function loadCannedKit(kitIndex) {
  var style = currentStyle();
  cannedKitIndex = ((kitIndex % style.kits.length) + style.kits.length) % style.kits.length;
  var kit = style.kits[cannedKitIndex];
  setUnlockedRows(function (v) {
    var id = VOICES[v].id;
    if (style.kind === "grids") {
      var row = gridsRow(v, kit.x, kit.y);
      return row ? { row: row, source: kit.name } : null;
    }
    return { row: parseRow(kit.rows[id] || "................", style.name + " / " + kit.name + " / " + id), source: kit.name };
  }, "canned kit");
}

/** A row for voice v from the style, different from its row now when the style has another. */
function freshRow(v, sharedGridsPoint) {
  var style = currentStyle(), id = VOICES[v].id, attempt, made = null;
  for (attempt = 0; attempt < 12; attempt++) {
    if (style.kind === "grids") {
      var point = sharedGridsPoint || { x: randomByte(), y: randomByte() };
      var row = gridsRow(v, point.x, point.y);
      if (!row) return null;
      made = { row: row, source: "grids " + point.x + "," + point.y };
    } else if (style.kind === "euclid") {
      var range = style.euclid[id];
      if (!range) return null;
      var k = range[0] + randomInt(range[1] - range[0] + 1), rotation = randomInt(STEPS);
      made = { row: euclideanRow(k, rotation), source: "E(" + k + ",16)" + (rotation ? " +" + rotation : "") };
    } else {
      var pool = style.pool[id];
      if (!pool || !pool.length) return null;
      var pick = pool[randomInt(pool.length)];
      made = { row: parseRow(pick.row, style.name + " pool / " + id), source: pick.source };
    }
    if (sharedGridsPoint || rowText(made.row) !== rowText(pattern[v])) return made;
  }
  return made;   // the style has only this row for the voice
}

function generate() {
  // Grids: one map point for the whole kit (its channels belong together); otherwise a row per voice
  var point = currentStyle().kind === "grids" ? { x: randomByte(), y: randomByte() } : null;
  setUnlockedRows(function (v) { return freshRow(v, point); }, "generate");
}

function reroll(v) {
  if (locks[v]) {
    post(DEVICE_NAME + ": " + VOICES[v].name + " is locked: unlock it to reroll\n");
    return false;
  }
  var made = freshRow(v, null);
  if (!made) {
    post(DEVICE_NAME + ": reroll: " + currentStyle().name + " has nothing for " + VOICES[v].name + ": kept as it was\n");
    return false;
  }
  if (rowText(made.row) === rowText(pattern[v])) post(DEVICE_NAME + ": reroll: " + currentStyle().name +
                                                    " has only this row for " + VOICES[v].name + "\n");
  pattern[v] = made.row;
  rowSources[v] = made.source;
  return true;
}

// ---- playing ------------------------------------------------------------------------------------------

/** Grids' perturbation for one pass: random byte x (randomness >> 2) >> 8, randomness = Variation as 0-255. */
function drawPerturbation() {
  var randomness = Math.round(variation * 255);
  return (randomByte() * (randomness >> 2)) >> 8;
}

function startPass(bar) {
  passBar = bar;
  for (var v = 0; v < VOICES.length; v++) passPerturbation[v] = drawPerturbation();
  var every = FILL_EVERY_BARS[fillChoice];
  passIsFillBar = every > 0 && variation > 0 && ((bar + 1) % every === 0);
  outlet(1, "fillbar", passIsFillBar ? 1 : 0);
  outlet(2, "bar", every > 0 ? ((bar % every) + every) % every + 1 : 0, every);
}

/** Where every second 16th falls, as a delay in ms at Live's tempo: (swing - 50%) of an 8th. */
function swingDelayMs(step) {
  if (step % 2 === 0) return 0;
  var eighthMs = 30000 / Math.max(20, tempo);
  return (SWING_PERCENT[swingLevel] / 100 - 0.5) * eighthMs;
}

/** The velocity a fired step plays at: 1 for an accent, else 0.5 to 0.8 up the level (see the README). */
function velocityForLevel(level) {
  return level > ACCENT_LEVEL_ABOVE ? 1 : 0.5 + 0.3 * Math.min(level, ACCENT_LEVEL_ABOVE) / ACCENT_LEVEL_ABOVE;
}

function trigger(v, velocity, delayMs) {
  triggerSerial[v] = (triggerSerial[v] % TRIGGER_SERIAL_WRAP) + 1;
  var id = VOICES[v].id;
  outlet(0, "delay_" + id, delayMs);
  outlet(0, "trig_" + id, triggerSerial[v] + Math.max(0.001, Math.min(1, velocity)) * 0.5);
  outlet(3, "hit", v, velocity);
}

/** What step `step` of the current pass plays: [{voice, velocity}], before swing. */
function hitsForStep(step) {
  var threshold = 255 - Math.round(density * 255);
  var inFillWindow = passIsFillBar && step >= FILL_WINDOW_FIRST_STEP;
  var hits = [];
  for (var v = 0; v < VOICES.length; v++) {
    if (mutes[v]) continue;
    var level = GRADE_LEVELS[pattern[v][step]];
    if (inFillWindow && VOICES[v].fills && pattern[v][step] === 0 && rowHasHits(pattern[v]) &&
        Math.random() < variation * 0.5) level = GRADE_LEVELS[FILL_HIT_GRADE];
    level = Math.min(255, level + passPerturbation[v]);
    if (!(level > threshold)) continue;
    var played = v;
    if (inFillWindow && VOICES[v].id === "oh" && Math.random() < variation) played = VOICE_INDEX_BY_ID.ch;
    hits.push({ voice: played, velocity: velocityForLevel(level) });
  }
  return hits;
}

/** Called by the kit's clock once for every 16th of the song while Live plays. */
function playSixteenth(songSixteenth) {
  var step = ((songSixteenth % STEPS) + STEPS) % STEPS;
  var bar = Math.floor(songSixteenth / STEPS);
  if (bar !== passBar) startPass(bar);
  outlet(1, "pos", step);
  var hits = hitsForStep(step), delayMs = swingDelayMs(step);
  for (var i = 0; i < hits.length; i++) {
    trigger(hits[i].voice, hits[i].velocity, delayMs);
    outlet(1, "hit", hits[i].voice, step);
  }
}

// ---- displays and storage --------------------------------------------------------------------------------

function showPattern() {
  var rows = ["rows"], sources = ["sources"];
  for (var v = 0; v < VOICES.length; v++) { rows.push(rowText(pattern[v])); sources.push(rowSources[v] || "-"); }
  outlet(1, rows);
  outlet(1, ["locks"].concat(locks));
  outlet(1, ["mutes"].concat(mutes));
  outlet(2, sources);
}
function showStyle() {
  var style = currentStyle();
  outlet(2, "style", style.name, style.tempo, style.swing, style.kits[cannedKitIndex].name);
}

function storedHalves(v) {
  var a = 0, b = 0;
  for (var s = 0; s < 8; s++) { a += pattern[v][s] << (2 * s); b += pattern[v][s + 8] << (2 * s); }
  return [a, b];
}
function bits(flags) { var n = 0; for (var v = 0; v < flags.length; v++) if (flags[v]) n |= 1 << v; return n; }
function storeVoice(v) {
  var halves = storedHalves(v);
  outlet(4, "steps_" + VOICES[v].id + "_a", halves[0]);
  outlet(4, "steps_" + VOICES[v].id + "_b", halves[1]);
}
function storeAll() {
  for (var v = 0; v < VOICES.length; v++) storeVoice(v);
  outlet(4, "locks", bits(locks));
  outlet(4, "mutes", bits(mutes));
}
function restoreHalf(v, half, value) {
  var packed = controlInt("the stored steps of " + VOICES[v].name, value, 0, 65535);
  for (var s = 0; s < 8; s++) pattern[v][s + 8 * half] = (packed >> (2 * s)) & 3;
  rowSources[v] = "saved";
}
function restoreFlags(flags, value, what) {
  var packed = controlInt("the stored " + what, value, 0, (1 << VOICES.length) - 1);
  for (var v = 0; v < VOICES.length; v++) flags[v] = (packed >> v) & 1;
}

/** After the pattern changed: show it and store it with the set. */
function changed() { showPattern(); showStyle(); storeAll(); }

// ---- messages ---------------------------------------------------------------------------------------------

function list(pitch, velocity) {
  if (inlet !== 0) {
    error(DEVICE_NAME + ": the control inlet got a bare list (" + arrayfromargs(arguments).join(" ") + "): ignored\n");
    return;
  }
  if (!(velocity > 0)) return;                       // note-offs: drums don't hold
  var v = VOICE_INDEX_BY_NOTE[pitch];
  if (v === undefined) {
    post(DEVICE_NAME + ": note " + pitch + " plays no voice (the voices are on " + VOICES.map(function (x) {
      return x.name + " " + x.notes.join("/"); }).join(", ") + ")\n");
    return;
  }
  trigger(v, Math.min(1, velocity / 127), 0);
}

function anything() {
  if (inlet !== 1) {
    error(DEVICE_NAME + ": the note inlet got '" + messagename + "' (it takes pitch velocity lists): ignored\n");
    return;
  }
  var a = arrayfromargs(arguments), value = a[0], v;
  var storedStep = /^steps_([a-z]+)_([ab])$/.exec(messagename);
  if (storedStep) {
    v = VOICE_INDEX_BY_ID[storedStep[1]];
    if (v === undefined) { error(DEVICE_NAME + ": stored steps for an unknown voice '" + storedStep[1] + "': ignored\n"); return; }
    restoreHalf(v, storedStep[2] === "a" ? 0 : 1, value);
    if (ready) showPattern();
    return;
  }
  switch (messagename) {
    case "style":
      if (!ready) break;                   // while Live restores the set, the stored steps win
      styleIndex = controlInt("Style", value, 0, STYLES.length - 1);
      loadCannedKit(0);
      changed();
      break;
    case "canned": loadCannedKit(cannedKitIndex + 1); changed(); break;
    case "generate": generate(); changed(); break;
    case "reroll": if (reroll(voiceArgument("reroll", value))) changed(); break;
    case "lock": v = voiceArgument("lock", value); locks[v] = locks[v] ? 0 : 1; changed(); break;
    case "mute": v = voiceArgument("mute", value); mutes[v] = mutes[v] ? 0 : 1; changed(); break;
    case "edit":
      v = voiceArgument("edit", value);
      var step = controlInt("the grid's edit step", a[1], 0, STEPS - 1);
      pattern[v][step] = a.length > 2 ? controlInt("the grid's edit grade", a[2], 0, 3)
                                       : [2, 2, 3, 0][pattern[v][step]];   // rest/ghost -> hit -> accent -> rest
      rowSources[v] = "edited";
      changed();
      break;
    case "variation": variation = controlUnit("Variation", value); break;
    case "density": density = controlUnit("Density", value); break;
    case "swing": swingLevel = controlInt("Swing", value, 0, SWING_PERCENT.length - 1); break;
    case "fill": fillChoice = controlInt("Fill", value, 0, FILL_EVERY_BARS.length - 1); passBar = null; break;
    case "locks": restoreFlags(locks, value, "locks"); if (ready) showPattern(); break;
    case "mutes": restoreFlags(mutes, value, "mutes"); if (ready) showPattern(); break;
    case "tempo":
      if (!(value >= 20 && value <= 999)) error(DEVICE_NAME + ": Live's tempo came as " + value + ": swing uses 120\n");
      tempo = value >= 20 && value <= 999 ? value : 120;
      break;
    case "playing":
      playing = value ? 1 : 0;
      resetClock();
      passBar = null;
      if (!playing) outlet(1, "pos", -1);
      break;
    case "tick": tick(value); break;
    case "ready": ready = 1; showPattern(); showStyle(); break;
    case "stop": passBar = null; outlet(1, "pos", -1); break;
    default:
      error(DEVICE_NAME + ": the brain doesn't know the message '" + messagename + "': ignored\n");
  }
}

// the Init pattern, until Live restores the saved one
loadCannedKit(0);
